function check() {
  const raiz = doc.documentElement
  const alto = (sel) => Math.round(doc.querySelector(sel)?.getBoundingClientRect().height ?? 0)
  const apretadas = CAJAS.map((s) => [s, doc.querySelector(s)])
    .filter(([, e]) => e && e.scrollWidth > e.clientWidth + 1)
    .map(([s]) => s)
  const overflowX = raiz.scrollWidth > raiz.clientWidth || apretadas.length > 0
  if (apretadas.length) console.warn('[faroPreview] se sale a lo ancho:', apretadas.join(', '))

  // El chip de ubicación NO entra en la cuenta: recortarse es su trabajo
  // (panel.css lo dice: cede él antes que las acciones). Pero cuando lo que se
  // recorta es la CLAVE —y no el título, que tiene elipsis— conviene saberlo,
  // porque entonces el corte es seco y no unos puntos.
  const chip = doc.querySelector('.chip')
  if (chip && chip.scrollWidth > chip.clientWidth + 1) {
    console.info('[faroPreview] el chip recorta: a esta anchura ya no cabe la clave entera')
  }
  const topHeight = alto('.top')
  const composerMetaHeight = alto('.composer-meta')

  const abiertas = [...doc.querySelectorAll('.screen:not(.hidden)')]
  const screenHeadsVisible = abiertas.every((s) => {
    const cabeceras = [...s.querySelectorAll('.screen-head')].filter((h) => h.getClientRects().length)
    return (
      cabeceras.length > 0 &&
      cabeceras.every((h) => {
        const r = h.getBoundingClientRect()
        return r.height > 0 && r.top >= -1 && r.bottom <= win.innerHeight + 1
      })
    )
  })

  const emptyStateRows = doc.querySelectorAll('.empty .suggestion').length

  // Los chips: en qué filas caen (por la coordenada de su caja, que es lo que
  // el navegador decidió de verdad) y cuántos se recortan.
  const chips = [...doc.querySelectorAll('.empty .search-chip')]
  const chipRows = new Set(chips.map((c) => Math.round(c.getBoundingClientRect().top))).size
  const chipsClipped = chips.filter((c) => c.scrollWidth > c.clientWidth + 1).length

  // Y si el estado vacío entero cabe: con él delante, el chat no tiene que
  // desplazarse (una conversación sí, y por eso sólo se mide con el vacío).
  const vacio = doc.querySelector('.empty')
  const caja = doc.querySelector('.chat')
  const emptyFits = !vacio || !caja || caja.scrollHeight <= caja.clientHeight + 1

  // Y cuánto de «hoy» hay en el estado vacío: cuántas filas y si se ha
  // quedado en la línea de «Qué mirar hoy (N)». No son veredictos —el panel
  // pinta una cosa o la otra a propósito—, sino lo que explica el
  // `emptyFits` de al lado: si las tres filas están puestas y el estado vacío
  // no cabe, es que había que degradarlo (decisión 3 de docs/PLAN.md §3.4).
  const todayRows = doc.querySelectorAll('.empty .today .today-row').length
  const todayLine = !!doc.querySelector('.empty .today .today-more') && todayRows === 0

  // ¿Hay panel? Las tres piezas que sostienen las medidas de arriba, y que
  // midan algo: un 0 px no es «cabe de sobra», es que no está pintado.
  const falta = ['#app', '.top', '.composer-meta'].filter((s) => !doc.querySelector(s))
  const motivo = falta.length
    ? 'no hay panel que medir: falta ' + falta.join(', ')
    : topHeight < 1 || composerMetaHeight < 1
      ? `el panel no está pintado: cabecera ${topHeight} px, fila del redactor ${composerMetaHeight} px`
      : ''
  const presente = !motivo

  const ok =
    presente &&
    !overflowX &&
    topHeight <= 48 &&
    composerMetaHeight <= 36 &&
    screenHeadsVisible &&
    emptyStateRows <= 3 &&
    chipsClipped === 0 &&
    emptyFits
  return {
    ok,
    motivo,
    overflowX,
    topHeight,
    composerMetaHeight,
    screenHeadsVisible,
    emptyStateRows,
    chipRows,
    chipsClipped,
    emptyFits,
    todayRows,
    todayLine,
  }
}

  // Los mandos también son API: el orquestador hace las capturas sin pulsar, y
  // cada uno devuelve las medidas de después, que es lo que va a la PR.
