)
const vacios63 = ambitos63.emptyContexts()
const construidos63 = ambitos63.withContext(
  ambitos63.withContext(vacios63, 'space:ENG', { text: 'x', indexedAt: Date.now() }),
  'space:OPS',
  { text: 'x', indexedAt: Date.now() }
